"""Generated by deploy/build_bundle.py from contracts/releases.py and contracts/goal.py.
Comments removed to keep the deploy small; read them in those files."""
PYPI = 'pypi'
NPM = 'npm'
REGISTRIES = (PYPI, NPM)
SHIPPED = 'shipped'
UNCLAIMED = 'unclaimed'
NOT_YET = 'not_yet'
UNKNOWN = 'unknown'
VERDICTS = (SHIPPED, UNCLAIMED, NOT_YET, UNKNOWN)
MIN_LEAD = 3600
MAX_LEAD = 366 * 24 * 3600
_MAX_NAME = 100

def normalise_package(registry: str, name: str) -> str:
    n = (name or '').strip()
    if registry == PYPI:
        out = []
        for ch in n.lower():
            if ch in '-_.':
                if not out or out[-1] != '-':
                    out.append('-')
            else:
                out.append(ch)
        return ''.join(out)
    return n.lower()

def valid_package(registry: str, name: str) -> bool:
    n = (name or '').strip()
    if not n or len(n) > _MAX_NAME:
        return False
    if registry == PYPI:
        if not (n[0].isalnum() and n[-1].isalnum() and n.isascii()):
            return False
        return all((ch.isalnum() or ch in '-_.' for ch in n))
    if registry == NPM:
        if n != n.lower() or not n.isascii():
            return False
        body = n
        if n.startswith('@'):
            if n.count('/') != 1:
                return False
            scope, body = n[1:].split('/')
            if not scope or not _npm_part(scope):
                return False
        elif '/' in n:
            return False
        return bool(body) and _npm_part(body) and (body[0] not in '._')
    return False

def _npm_part(part: str) -> bool:
    return all(('a' <= ch <= 'z' or '0' <= ch <= '9' or ch in '-._~' for ch in part))

def valid_version(version: str) -> bool:
    v = (version or '').strip()
    if not v or len(v) > 40 or (not v.isascii()):
        return False
    i = 0
    groups = 0
    while True:
        start = i
        while i < len(v) and v[i].isdigit():
            i += 1
        if i == start:
            return False
        groups += 1
        if i < len(v) and v[i] == '.' and (i + 1 < len(v)) and v[i + 1].isdigit():
            i += 1
            continue
        break
    if groups < 1 or groups > 4:
        return False
    tail = v[i:]
    if not tail:
        return True
    if tail[0] in '-.':
        tail = tail[1:]
    if not tail or not tail[0].isalpha():
        return False
    return all((ch.isalnum() or ch in '-.' for ch in tail)) and (not tail.endswith(('.', '-')))

def registry_url(registry: str, package: str, version: str) -> str:
    name = normalise_package(registry, package)
    v = version.strip()
    if registry == PYPI:
        return 'https://pypi.org/pypi/' + name + '/' + v + '/json'
    if registry == NPM:
        return 'https://registry.npmjs.org/' + name + '/' + v
    raise ValueError('unknown registry')

def names_version(body: str, version: str) -> bool:
    v = version.strip()
    text = body or ''
    return '"version":"' + v + '"' in text or '"version": "' + v + '"' in text

def names_payee(body: str, payee: str) -> bool:
    address = (payee or '').strip().lower()
    if len(address) != 42 or not address.startswith('0x'):
        return False
    return address in (body or '').lower()

def classify(status: int, body: str, version: str, payee: str) -> dict:
    code = int(status)
    if code == 200:
        if not names_version(body, version):
            return {'verdict': UNKNOWN, 'note': 'a 200 that did not name this version'}
        if names_payee(body, payee):
            return {'verdict': SHIPPED, 'note': 'the release names this payee'}
        return {'verdict': UNCLAIMED, 'note': 'the release does not name this payee'}
    if code == 404:
        return {'verdict': NOT_YET, 'note': 'the registry has no such version'}
    return {'verdict': UNKNOWN, 'note': 'the registry answered ' + str(code)}

def unreached() -> dict:
    return {'verdict': UNKNOWN, 'note': 'the registry could not be reached'}

def epoch_seconds(stamp: str):
    s = (stamp or '').strip()
    if len(s) < 19 or s[4] != '-' or s[7] != '-' or (s[10] != 'T') or (s[13] != ':') or (s[16] != ':'):
        return None
    for i in (0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15, 17, 18):
        if not '0' <= s[i] <= '9':
            return None
    year, month, day = (int(s[0:4]), int(s[5:7]), int(s[8:10]))
    hour, minute, second = (int(s[11:13]), int(s[14:16]), int(s[17:19]))
    if not 1 <= month <= 12 or day < 1 or day > _days_in_month(year, month):
        return None
    if hour > 23 or minute > 59 or second > 60:
        return None
    return _days_from_civil(year, month, day) * 86400 + hour * 3600 + minute * 60 + second

def _days_in_month(year: int, month: int) -> int:
    if month == 2:
        leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
        return 29 if leap else 28
    return 30 if month in (4, 6, 9, 11) else 31

def _days_from_civil(year: int, month: int, day: int) -> int:
    y = year - (1 if month <= 2 else 0)
    era = (y if y >= 0 else y - 399) // 400
    year_of_era = y - era * 400
    day_of_year = (153 * (month + (-3 if month > 2 else 9)) + 2) // 5 + day - 1
    day_of_era = year_of_era * 365 + year_of_era // 4 - year_of_era // 100 + day_of_year
    return era * 146097 + day_of_era - 719468
from dataclasses import dataclass
import genlayer as gl
from genlayer.types import *

@gl.storage.allow
@dataclass
class Target:
    organiser: Address
    name: str
    registry: str
    package: str
    version: str
    payee: Address
    posted_at: str
    deadline: u256

class GoalBook(gl.contract.Contract):
    goals: gl.storage.TreeMap[str, Target]
    goal_ids: gl.storage.DynArray[str]

    def __init__(self):
        pass

    @gl.public.write
    def post(self, name: str, registry: str, package: str, version: str, payee: str, hours: int) -> dict:
        label = name.strip().lower()
        if not label or len(label) > 40:
            raise gl.vm.UserError('name the goal')
        for ch in label:
            if not ('0' <= ch <= '9' or 'a' <= ch <= 'z' or ch in '-_'):
                raise gl.vm.UserError('a name is letters, digits, hyphen or underscore')
        reg = registry.strip().lower()
        if reg not in REGISTRIES:
            raise gl.vm.UserError('the registry is pypi or npm')
        if not valid_package(reg, package):
            raise gl.vm.UserError('that is not a package name ' + reg + ' would accept')
        if not valid_version(version):
            raise gl.vm.UserError('give the version exactly as the registry lists it, like 2.0.0')
        recipient = _address(payee)
        if recipient.as_hex.lower() == '0x' + '00' * 20:
            raise gl.vm.UserError('name a real payee')
        lead = int(hours) * 3600
        if lead < MIN_LEAD or lead > MAX_LEAD:
            raise gl.vm.UserError(f'a deadline is {MIN_LEAD // 3600} hour to {MAX_LEAD // 86400} days away')
        now = epoch_seconds(_stamp())
        if now is None:
            raise gl.vm.UserError('the clock could not be read')
        organiser = gl.message.sender_address
        goal_id = organiser.as_hex.lower() + ':' + label
        if goal_id in self.goals:
            raise gl.vm.UserError('that goal already exists and cannot be changed')
        self.goals[goal_id] = Target(organiser=organiser, name=label, registry=reg, package=normalise_package(reg, package), version=version.strip(), payee=recipient, posted_at=_stamp(), deadline=now + lead)
        self.goal_ids.append(goal_id)
        return _as_dict(goal_id, self.goals[goal_id])

    @gl.public.view
    def get(self, goal_id: str) -> dict:
        key = goal_id.strip().lower()
        if key not in self.goals:
            raise gl.vm.UserError('no such goal: ' + key)
        return _as_dict(key, self.goals[key])

    @gl.public.view
    def goal_list(self) -> list:
        return [g for g in self.goal_ids]

def _stamp() -> str:
    return str(gl.message.raw['datetime'])

def _address(value) -> Address:
    if hasattr(value, 'as_hex'):
        return value
    return Address(str(value).strip())

def _as_dict(key: str, target: Target) -> dict:
    return {'goal_id': key, 'organiser': target.organiser.as_hex, 'name': target.name, 'registry': target.registry, 'package': target.package, 'version': target.version, 'url': registry_url(target.registry, target.package, target.version), 'payee': target.payee.as_hex, 'posted_at': target.posted_at, 'deadline': str(target.deadline)}
